const input = $input.first().json;

// EDIT ONLY THESE FOUR VALUES AFTER IMPORTING THE WORKFLOW.
const config = {
  phantombuster_agent_id: 'PASTE_PHANTOMBUSTER_AGENT_ID',
  unipile_account_id: 'PASTE_UNIPILE_ACCOUNT_ID',
  gemini_model: 'gemini-3.1-flash-lite',
  smtp_from_email: 'PASTE_SENDER_EMAIL',
  webhook_secret: 'PASTE_WEBHOOK_SECRET'
};

const missing = Object.entries(config)
  .filter(([, value]) => String(value).includes('PASTE_'))
  .map(([key]) => key);

if (missing.length) {
  throw new Error('Open the CONFIG — EDIT ME node and fill: ' + missing.join(', '));
}

return [{ json: { ...input, ...config } }];

const data = $input.first().json;
const csv = String(data.leads_csv || data['Paste leads CSV'] || '').trim();
if (!csv) throw new Error('The leads CSV field is empty.');

function parseCsv(text) {
  const rows = [];
  let row = [], field = '', quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '"') {
      if (quoted && text[i + 1] === '"') { field += '"'; i++; }
      else quoted = !quoted;
    } else if (ch === ',' && !quoted) {
      row.push(field.trim()); field = '';
    } else if ((ch === '\n' || ch === '\r') && !quoted) {
      if (ch === '\r' && text[i + 1] === '\n') i++;
      row.push(field.trim()); field = '';
      if (row.some(Boolean)) rows.push(row);
      row = [];
    } else field += ch;
  }
  row.push(field.trim());
  if (row.some(Boolean)) rows.push(row);
  return rows;
}

const rows = parseCsv(csv);
const headers = rows.shift().map(h => h.toLowerCase().trim());
const urlIndex = headers.indexOf('linkedin_url');
if (urlIndex < 0) throw new Error('CSV must contain a linkedin_url column.');

const firstNameIndex = headers.indexOf('first_name');
const companyIndex = headers.indexOf('company');
const seen = new Set();
const leads = [];

for (const row of rows) {
  const url = String(row[urlIndex] || '').trim().split('?')[0].replace(/\/$/, '');
  if (!/^https:\/\/(www\.)?linkedin\.com\/in\/[a-zA-Z0-9_%.-]+$/.test(url)) continue;
  if (seen.has(url.toLowerCase())) continue;
  seen.add(url.toLowerCase());
  leads.push({
    json: {
      ...data,
      linkedin_url: url,
      public_identifier: url.split('/in/')[1],
      first_name: firstNameIndex >= 0 ? String(row[firstNameIndex] || '').trim() : '',
      company: companyIndex >= 0 ? String(row[companyIndex] || '').trim() : '',
      status: 'NEW'
    }
  });
  if (leads.length >= 25) break;
}

if (!leads.length) throw new Error('No valid LinkedIn profile URLs were found.');

const state = $getWorkflowStaticData('global');
state.owner_email = data.owner_email || data['Your email'] || '';
state.smtp_from_email = data.smtp_from_email;
state.webhook_secret = data.webhook_secret;
state.sent = state.sent || {};
state.chats = state.chats || {};
state.replies = state.replies || [];

return leads;

const lead = $('Loop Over Leads').first().json;
const response = $input.first().json;
const containerId = response.containerId || response.id || response.container_id || response.container?.id;
if (!containerId) throw new Error('PhantomBuster launch did not return a container ID. Open this execution and inspect Launch PhantomBuster output.');
return [{ json: { ...lead, container_id: String(containerId) } }];

const downloaded = $input.first().json;

let lead = {};
let container = { status: 'finished' };

// Normal full-workflow execution uses these earlier nodes. The fallbacks let
// this node be tested by itself with pinned/downloaded CSV data.
try { lead = $('Remember Lead + Container').first().json; } catch {}
try { container = $('Get PhantomBuster Result').first().json; } catch {}

if (String(container.status || '').toLowerCase() !== 'finished') {
  return [{
    json: {
      ...lead,
      status: 'FAILED',
      post_found: false,
      error: 'PhantomBuster has not finished yet.'
    }
  }];
}

const csvText = String(
  downloaded.csv_text ??
  downloaded.data ??
  downloaded.body ??
  ''
);

if (!csvText.trim()) {
  return [{
    json: {
      ...lead,
      status: 'FAILED',
      post_found: false,
      error: 'The downloaded PhantomBuster CSV was empty.'
    }
  }];
}

function parseCsv(text) {
  const records = [];
  let record = [];
  let field = '';
  let insideQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const character = text[i];
    const nextCharacter = text[i + 1];

    if (character === '"' && insideQuotes && nextCharacter === '"') {
      field += '"';
      i++;
    } else if (character === '"') {
      insideQuotes = !insideQuotes;
    } else if (character === ',' && !insideQuotes) {
      record.push(field);
      field = '';
    } else if (
      (character === '\n' || character === '\r') &&
      !insideQuotes
    ) {
      if (character === '\r' && nextCharacter === '\n') {
        i++;
      }

      record.push(field);
      field = '';

      if (record.some(value => String(value).trim())) {
        records.push(record);
      }

      record = [];
    } else {
      field += character;
    }
  }

  record.push(field);

  if (record.some(value => String(value).trim())) {
    records.push(record);
  }

  if (records.length < 2) {
    return [];
  }

  const headers = records.shift().map(header =>
    String(header).replace(/^\uFEFF/, '').trim()
  );

  return records.map(values => {
    const row = {};

    headers.forEach((header, index) => {
      row[header] = values[index] ?? '';
    });

    return row;
  });
}

function normalizeKey(key) {
  return String(key || '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

function firstValue(object, possibleKeys) {
  const normalizedValues = new Map(
    Object.entries(object).map(([key, value]) => [
      normalizeKey(key),
      value
    ])
  );

  for (const key of possibleKeys) {
    const value = normalizedValues.get(normalizeKey(key));

    if (
      value !== undefined &&
      value !== null &&
      String(value).trim()
    ) {
      return value;
    }
  }

  return '';
}

function dateToMilliseconds(value) {
  if (typeof value === 'number') {
    return value > 1000000000000 ? value : value * 1000;
  }

  const text = String(value || '').trim();

  if (!text) {
    return NaN;
  }

  const parsedDate = Date.parse(text);

  if (!Number.isNaN(parsedDate)) {
    return parsedDate;
  }

  const relative = text.match(
    /(\d+)\s*(minute|hour|day|week|month|year)s?\s*ago/i
  );

  if (!relative) {
    return NaN;
  }

  const amount = Number(relative[1]);
  const unit = relative[2].toLowerCase();

  const multipliers = {
    minute: 60000,
    hour: 3600000,
    day: 86400000,
    week: 604800000,
    month: 2592000000,
    year: 31536000000
  };

  return Date.now() - amount * multipliers[unit];
}

const rows = parseCsv(csvText);

if (!rows.length) {
  return [{
    json: {
      ...lead,
      status: 'NO_POST',
      post_found: false,
      error: 'PhantomBuster result.csv did not contain any posts.'
    }
  }];
}

const textKeys = [
  'Post Content',
  'postContent',
  'postText',
  'post_text',
  'content',
  'text',
  'description'
];

const urlKeys = [
  'Post Url',
  'postUrl',
  'post_url',
  'postLink',
  'link',
  'url'
];

const dateKeys = [
  'postTimestamp',
  'publishedAt',
  'postedAt',
  'Post Date',
  'postDate',
  'post_date',
  'createdAt',
  'timestamp',
  'date'
];

// result.csv can contain historical rows for several profiles. Only use
// rows belonging to the current lead when the profile identifier is known.
const targetIdentifier = String(lead.public_identifier || '')
  .trim()
  .toLowerCase();

const authorMatchingRows = targetIdentifier
  ? rows.filter(row => String(firstValue(row, [
      'authorUrl',
      'authorProfileUrl'
    ]) || '').toLowerCase().includes('/in/' + targetIdentifier))
  : [];

const profileMatchingRows = targetIdentifier
  ? rows.filter(row => String(firstValue(row, [
      'profileUrl',
      'linkedinProfileUrl'
    ]) || '').toLowerCase().includes('/in/' + targetIdentifier))
  : [];

// Prefer rows whose actual author is the lead. Use profileUrl only as a
// fallback because PhantomBuster may also return group/community activity.
const matchingRows = authorMatchingRows.length
  ? authorMatchingRows
  : profileMatchingRows;

const candidateRows = matchingRows.length ? matchingRows : rows;

// When testing this node alone, infer the lead from PhantomBuster's CSV.
if (!lead.linkedin_url && candidateRows.length) {
  const inferredUrl = String(firstValue(candidateRows[0], [
    'profileUrl',
    'authorUrl',
    'linkedinProfileUrl'
  ]) || '').split('?')[0].replace(/\/$/, '');

  if (/linkedin\.com\/in\//i.test(inferredUrl)) {
    lead.linkedin_url = inferredUrl;
    lead.public_identifier = inferredUrl.split('/in/')[1] || '';
  }

  lead.first_name = lead.first_name || String(
    firstValue(candidateRows[0], ['author', 'authorName', 'fullName']) || ''
  ).trim().split(/\s+/)[0];
}

// Standalone testing learns the target from profileUrl first, then applies
// the same author-first filtering used during a complete workflow run.
let finalCandidateRows = candidateRows;
if (!targetIdentifier && lead.public_identifier) {
  const inferredIdentifier = String(lead.public_identifier).toLowerCase();
  const inferredAuthorRows = rows.filter(row => String(firstValue(row, [
    'authorUrl',
    'authorProfileUrl'
  ]) || '').toLowerCase().includes('/in/' + inferredIdentifier));
  const inferredProfileRows = rows.filter(row => String(firstValue(row, [
    'profileUrl',
    'linkedinProfileUrl'
  ]) || '').toLowerCase().includes('/in/' + inferredIdentifier));
  finalCandidateRows = inferredAuthorRows.length
    ? inferredAuthorRows
    : (inferredProfileRows.length ? inferredProfileRows : rows);
  lead.first_name = String(firstValue(finalCandidateRows[0] || {}, [
    'author',
    'authorName',
    'fullName'
  ]) || lead.first_name || '').trim().split(/\s+/)[0];
}

const posts = finalCandidateRows
  .map((row, originalOrder) => {
    const text = String(firstValue(row, textKeys)).trim();
    const postUrl = String(firstValue(row, urlKeys)).trim();
    const rawDate = firstValue(row, dateKeys);
    const dateMs = dateToMilliseconds(rawDate);

    const typeText = String(
      firstValue(row, [
        'Type',
        'Activity Type',
        'activityType',
        'action'
      ])
    ).toLowerCase();

    const isRepost =
      typeText.includes('repost') ||
      typeText.includes('reshare') ||
      String(row.isRepost || row.is_repost || '').toLowerCase() === 'true';

    return {
      text,
      postUrl,
      dateMs,
      isRepost,
      originalOrder
    };
  })
  .filter(post => post.text.length >= 40 && !post.isRepost);

if (!posts.length) {
  return [{
    json: {
      ...lead,
      status: 'NO_POST',
      post_found: false,
      error: 'No suitable text post was found in the PhantomBuster CSV.'
    }
  }];
}

const postsWithDates = posts.filter(post =>
  Number.isFinite(post.dateMs)
);

let latestPost;

if (postsWithDates.length) {
  const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;

  latestPost = postsWithDates
    .filter(post => post.dateMs >= cutoff)
    .sort((a, b) => b.dateMs - a.dateMs)[0];
} else {
  // PhantomBuster normally puts the newest result first.
  latestPost = posts.sort(
    (a, b) => a.originalOrder - b.originalOrder
  )[0];
}

if (!latestPost) {
  return [{
    json: {
      ...lead,
      status: 'NO_POST',
      post_found: false,
      error: 'No suitable post from the last 30 days was found.'
    }
  }];
}

return [{
  json: {
    ...lead,
    status: 'POST_FOUND',
    post_found: true,
    post_text: latestPost.text,
    post_url: latestPost.postUrl,
    post_date: Number.isFinite(latestPost.dateMs)
      ? new Date(latestPost.dateMs).toISOString()
      : '',
    post_date_missing: !Number.isFinite(latestPost.dateMs),
    error: ''
  }
}];

const lead = $('Extract Latest Post').first().json;
const raw = $input.first().json;
const profile = raw.data || raw;

if (profile.object === 'AccountList') {
  throw new Error(
    'Get Unipile Profile is still using the /accounts test URL. Restore the /users/{identifier} URL.'
  );
}

const networkDistance = String(
  profile.specifics?.network_distance ||
  profile.network_distance ||
  ''
).toUpperCase();

const isConnected =
  profile.is_relationship === true ||
  networkDistance === 'FIRST_DEGREE' ||
  networkDistance === 'DISTANCE_1';

return [{
  json: {
    ...lead,
    unipile_user_id:
      profile.provider_id ||
      profile.id ||
      '',
    connection_status: networkDistance,
    is_connected: isConnected,
    status: isConnected
      ? 'CONNECTED'
      : 'NOT_CONNECTED',
  },
}];

const lead = $('Check Connection').item.json;
const response = $input.first().json;
const rawText = (response.candidates?.[0]?.content?.parts || []).map(part => part.text || '').join('').trim();
let parsed;
try {
  parsed = JSON.parse(rawText.replace(/^\s*\x60\x60\x60json\s*|\s*\x60\x60\x60\s*$/gi, ''));
} catch {
  return [{ json: { ...lead, status: 'FAILED', valid_draft: false, error: 'Gemini did not return valid JSON.' } }];
}

const message = String(parsed.message || '').trim();
const detail = String(parsed.detail_used || '').trim();
const invalid = message.length < 250 || message.length > 400 || !message.includes('?') || /https?:\/\//i.test(message) || /book a call|schedule a call|my service|our service/i.test(message);

const detailWords = detail.toLowerCase().match(/[a-z0-9$%]+/g) || [];
const postLower = lead.post_text.toLowerCase();
const supported = detailWords.filter(word => word.length > 3 || /\d/.test(word)).slice(0, 5).some(word => postLower.includes(word));

return [{ json: {
  ...lead,
  draft_message: message,
  detail_used: detail,
  valid_draft: !invalid && supported,
  status: !invalid && supported ? 'READY_FOR_REVIEW' : 'FAILED',
  error: !invalid && supported ? '' : 'The generated message failed length, question, URL, sales-language, or source-detail validation.'
} }];

const draft = $('Parse Gemini Draft').item.json;
const response = $input.first().json.data || {};
const decision = String(response.decision || response.Decision || '').trim();
const finalMessage = String(response.final_message || response['final message'] || draft.draft_message || '').trim();
return [{ json: {
  ...draft,
  decision,
  final_message: finalMessage,
  approved: decision.toLowerCase() === 'approve'
} }];

const lead = $input.first().json;
const state = $getWorkflowStaticData('global');
state.sent = state.sent || {};
const today = new Date().toISOString().slice(0, 10);
const sentToday = Object.values(state.sent).filter(entry => entry?.date === today).length;
const alreadySent = Boolean(state.sent[lead.linkedin_url]);
const textValid = lead.final_message.length >= 250 && lead.final_message.length <= 400 && lead.final_message.includes('?') && !/https?:\/\//i.test(lead.final_message);
let reason = '';
if (alreadySent) reason = 'This lead has already received a message.';
else if (sentToday >= 25) reason = 'The daily limit of 25 messages has been reached.';
else if (!textValid) reason = 'The edited message failed final validation.';
return [{ json: { ...lead, can_send: !reason, send_block_reason: reason, sent_today: sentToday } }];

const lead = $('Daily Limit + Duplicate Guard').item.json;
const raw = $input.first().json;
const profile = raw.data || raw;
const distance = String(
  profile.specifics?.network_distance ||
  profile.network_distance ||
  ''
).toUpperCase();
const stillConnected =
  profile.is_relationship === true ||
  distance === 'FIRST_DEGREE' ||
  distance === 'DISTANCE_1';
return [{ json: {
  ...lead,
  still_connected: stillConnected,
  connection_status: distance,
  unipile_user_id: profile.provider_id || profile.id || lead.unipile_user_id
} }];

const lead = $('Confirm Still Connected').item.json;
const response = $input.first().json;
const sent = response.data || response;
const chatId = sent.chat_id || sent.id || sent.chat?.id || '';
const state = $getWorkflowStaticData('global');
state.sent = state.sent || {};
state.chats = state.chats || {};
const now = new Date().toISOString();
state.sent[lead.linkedin_url] = { date: now.slice(0, 10), sent_at: now, chat_id: chatId, first_name: lead.first_name, message: lead.final_message };
if (chatId) state.chats[chatId] = { linkedin_url: lead.linkedin_url, first_name: lead.first_name, company: lead.company, sent_at: now };
return [{ json: { ...lead, status: 'SENT', sent_at: now, unipile_chat_id: chatId } }];

const state = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
const sentToday = Object.values(state.sent || {}).filter(entry => entry?.date === today).length;
return [{ json: { finished: true, sent_today: sentToday, total_recorded_sends: Object.keys(state.sent || {}).length, recorded_replies: (state.replies || []).length } }];

const incoming = $input.first().json;
const event = incoming.body || incoming;
const headers = incoming.headers || {};
const state = $getWorkflowStaticData('global');

// Validate secret only when a real secret has been configured.
const expectedSecret = state.webhook_secret || '';
const suppliedSecret =
  headers['x-webhook-secret'] ||
  headers['X-Webhook-Secret'] ||
  '';

const secretConfigured =
  expectedSecret &&
  expectedSecret !== 'CHANGE_THIS_TO_A_LONG_RANDOM_SECRET';

if (secretConfigured && suppliedSecret !== expectedSecret) {
  return [];
}

// Accept Unipile v1 and v2 messages.
const isV1Message = event.event === 'message_received';
const isV2Message = event.type === 'message.new';

if (!isV1Message && !isV2Message) {
  return [];
}

const message = isV2Message ? event.payload || {} : event;

// Ignore messages sent by your own LinkedIn account.
const senderProviderId =
  message.sender?.attendee_provider_id ||
  event.sender?.attendee_provider_id ||
  '';

const connectedAccountUserId =
  event.account_info?.user_id ||
  event.account?.user_id ||
  '';

const sentByMe =
  message.is_sender === true ||
  Boolean(
    senderProviderId &&
    connectedAccountUserId &&
    senderProviderId === connectedAccountUserId
  );

if (sentByMe) {
  return [];
}

const chatId = message.chat_id || event.chat_id || '';

const messageId =
  message.id ||
  message.message_id ||
  event.message_id ||
  '';

const replyText =
  message.text ||
  message.message ||
  event.message ||
  '';

if (!chatId || !replyText) {
  return [];
}

state.replies = state.replies || [];

// Prevent duplicate email notifications.
const alreadyRecorded = state.replies.some(
  item => item.message_id && item.message_id === messageId
);

if (alreadyRecorded) {
  return [];
}

const savedLead = (state.chats || {})[chatId] || {};

const reply = {
  chat_id: chatId,
  message_id: messageId,
  reply_text: replyText,
  replied_at:
    event.created_at ||
    event.timestamp ||
    message.timestamp ||
    new Date().toISOString(),

  linkedin_url:
    savedLead.linkedin_url ||
    message.sender?.attendee_profile_url ||
    event.sender?.attendee_profile_url ||
    '',

  first_name:
    savedLead.first_name ||
    message.sender?.attendee_name ||
    event.sender?.attendee_name ||
    'LinkedIn lead'
};

state.replies.push(reply);
return [{
  json: {
    ...reply,
    owner_email: state.owner_email || '',
    smtp_from_email: state.smtp_from_email || '',
    has_owner_email: Boolean(
      state.owner_email &&
      state.smtp_from_email
    )
  }
}];
